def get_caliper_analytics_spec_catalog() -> List[CaliperAnalyticsSpecRecord]:
    """Return complete caliper_analytics_spec registry."""
    return REGISTRY_CALIPER_ANALYTICS_SPEC


def query_caliper_analytics_spec_by_difficulty(difficulty_level: str) -> List[CaliperAnalyticsSpecRecord]:
    """Filter caliper_analytics_spec elements matching difficulty."""
    return [item for item in REGISTRY_CALIPER_ANALYTICS_SPEC if item.difficulty == difficulty_level]


def calculate_caliper_analytics_spec_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_CALIPER_ANALYTICS_SPEC)

